import{_ as t,C as s,o as i,c as r,a6 as o,E as l,j as a,a as u}from"./chunks/framework.CKIbuWFA.js";const b=JSON.parse('{"title":"Examiner les changements par domaine","description":"","frontmatter":{"title":"Examiner les changements par domaine","docId":"user.cloud.changes","translationKey":"user.cloud.changes","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"f875a22e66dd822d7ea1344188d8b7b087a23a777e072240a4a3c7c57969f995","translationRevision":"eaf4ca846ad1f45e40a499c945c0d8c1b150f1c027a4d840ecfc1bb831773d9c","order":20},"headers":[],"relativePath":"fr/user/cloud/changes.md","filePath":"fr/user/cloud/changes.md","lastUpdated":1794611623000}'),c={name:"fr/user/cloud/changes.md"};function p(d,e,m,v,g,h){const n=s("DemoFrame");return i(),r("div",null,[e[0]||(e[0]=o('<h1 id="review-changes-by-area" tabindex="-1">Examiner les changements par domaine <a class="header-anchor" href="#review-changes-by-area" aria-label="Permalink to &quot;Examiner les changements par domaine {#review-changes-by-area}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Comprendre ce qu’un panneau <strong>Changes</strong> compare avant de réinitialiser, envoyer ou adopter des données. Il faut du contenu local enregistré. Les opérations Cloud nécessitent en plus un hôte pris en charge, le mode de synchronisation approprié et un <a href="./account.html">compte connecté</a>. Les panneaux portant le même nom n’utilisent pas tous le même transport.</p><h2 id="review-events-and-actions-locally" tabindex="-1">Examiner Events et Actions localement <a class="header-anchor" href="#review-events-and-actions-locally" aria-label="Permalink to &quot;Examiner Events et Actions localement {#review-events-and-actions-locally}&quot;">​</a></h2><ol><li>Ouvrez <strong>Automations</strong>, sélectionnez Events ou Actions et ouvrez <strong>Changes</strong>.</li><li>Lisez l’avis : ce domaine compare les définitions actuelles à une référence conservée sur cet appareil. La première visite chargée initialise cette référence ; il est donc normal qu’elle puisse n’afficher aucun changement.</li><li>Sélectionnez un enregistrement ajouté, modifié ou supprimé et examinez les valeurs avant/après.</li><li>Choisissez <strong>Mark as reviewed</strong> uniquement pour faire de la section actuelle la nouvelle référence locale. Cela ne téléverse pas les définitions et n’approuve pas l’exécution déléguée.</li><li>Utilisez <strong>Reset</strong> uniquement pour restaurer la référence. Pour un nouvel enregistrement, la réinitialisation le supprime ; pour un enregistrement modifié/supprimé, elle restaure la définition conservée. Enregistrez d’abord une exportation si nécessaire.</li></ol><p>L’adaptateur Events/Actions n’a pas de collection Cloud pour les définitions individuelles dans cette version. Une comparaison sans changements n’est ni une sauvegarde Cloud ni la preuve qu’un autre ordinateur a reçu vos modifications.</p><h2 id="review-variables-and-plugins-explicitly" tabindex="-1">Examiner Variables et Plugins explicitement <a class="header-anchor" href="#review-variables-and-plugins-explicitly" aria-label="Permalink to &quot;Examiner Variables et Plugins explicitement {#review-variables-and-plugins-explicitly}&quot;">​</a></h2><p>Variables dispose de son propre partage natif avec examen : enregistrez localement, récupérez les propositions, examinez la comparaison et envoyez, appliquez/adoptez ou retirez explicitement. Les valeurs secrètes ou bloquées restent masquées et ne peuvent pas être envoyées par ce parcours. L’enregistrement local ne téléverse jamais. Consultez <a href="./../automations/variables.html">Variables</a>.</p><p>Plugin Changes utilise son espace de synchronisation pris en charge pour les sélections de plugins et les paramètres préparés. La publication s’effectue par section plutôt que par envoi séparé pour chaque ligne. Les paramètres affichent les noms de clés modifiées sans exposer leurs valeurs ; les conflits permettent de choisir la version locale ou Cloud, sans fusion arbitraire des champs. Lisez l’action de section et le mode de synchronisation sélectionné avant de publier.</p><p>Les incrustations Cloud utilisent le parcours de création/révision de la <a href="./../overlays/">bibliothèque et de l’éditeur</a>. Aucun adaptateur Changes partagé pour les incrustations n’est disponible dans cette version de base.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Résultat attendu, état et récupération <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Résultat attendu, état et récupération {#expected-result-status-and-recovery}&quot;">​</a></h2><p>La comparaison locale des automatisations et le partage natif conditionné aux capacités sont disponibles dans leurs domaines respectifs. Les opérations produisant des effets distants dépendent du service ; leur validation en production n’est pas implicite. Si un examen devient obsolète, actualisez et comparez à nouveau. Si le résultat n’est pas confirmé, consultez l’état ou le journal avant de créer une autre opération. Un délai d’attente dépassé ne prouve jamais qu’aucun changement n’a eu lieu.</p>',12)),l(n,{scenario:"cloud",locale:"fr",tour:"changes",title:"Démo : Cloud"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[u("Détails de fonctionnement "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Détails de fonctionnement {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"Avant préparation/migration v1 → v2, sauvegardez et coordonnez les versions compatibles sur tous les appareils. Dans setup, préparez, vérifiez la compatibilité et prévisualisez ; examinez sélections, attentes, conflits et éléments uniquement v1 sans les supposer synchronisés. Exiger l’en-tête d’époque est irréversible pour les écritures v2 du compte et peut refuser les anciens appareils. Un timeout de barrière est ambigu ; la répéter avance encore l’époque. Actualisez état époque/migration et aperçu avant d’agir. Lire l’époque ne prouve pas la fin des anciennes écritures.",-1)),e[3]||(e[3]=a("p",null,"La récupération dépend du mode : Changes Events/Actions compare des références locales sans écriture Cloud. Pour Variables/Plugins révisés, rechargez les comparaisons périmées et vérifiez révision, compte et inventaires. Si des plugins manquent, révisez/réparez l’inventaire setup puis recréez un aperçu. Pour une intention incertaine, conservez ID/preuves et consultez historique/état ; la récupération technique exige une nouvelle revue des entrées figées et de la révision Cloud. Reprendre cette intention n’envoie pas une écriture distante à lui seul. Arrêtez si la réconciliation reste impossible, sans mutation de remplacement.",-1))])}const x=t(c,[["render",p]]);export{b as __pageData,x as default};
